let payload = $json.body || $json || {};
if (typeof payload === 'string') {
  try { payload = JSON.parse(payload); } catch (e) {}
}
const row = payload.data || {};

function hasValue(v) {
  return v !== undefined && v !== null && String(v).trim() !== '';
}

function getField(name) {
  const keys = Object.keys(row);
  if (Object.prototype.hasOwnProperty.call(row, name) && hasValue(row[name])) {
    return row[name];
  }
  const matchedKeys = keys.filter(k => String(k).trim() === String(name).trim());
  for (const k of matchedKeys) {
    if (hasValue(row[k])) return row[k];
  }
  if (Object.prototype.hasOwnProperty.call(row, name)) return row[name];
  if (matchedKeys.length) return row[matchedKeys[0]];
  return '';
}

function getFileId(url) {
  if (!url) return '';
  const match = String(url).match(/[-\w]{25,}/);
  return match ? match[0] : '';
}

function safeText(value) {
  return String(value || '')
    .trim()
    .replace(/[\\/:*?"<>|]/g, '')
    .replace(/\s+/g, ' ');
}

function formatTanggal(value) {
  if (!value) return '';
  if (Object.prototype.toString.call(value) === '[object Date]' && !isNaN(value)) {
    const dd = String(value.getDate()).padStart(2, '0');
    const mm = String(value.getMonth() + 1).padStart(2, '0');
    const yyyy = value.getFullYear();
    return `${dd}-${mm}-${yyyy}`;
  }
  const str = String(value).trim();
  const mdyTime = str.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})(?:\s+\d{1,2}:\d{2}(?::\d{2})?)?$/);
  if (mdyTime) {
    const mm = String(mdyTime[1]).padStart(2, '0');
    const dd = String(mdyTime[2]).padStart(2, '0');
    const yyyy = mdyTime[3];
    return `${dd}-${mm}-${yyyy}`;
  }
  const dmyTime = str.match(/^(\d{1,2})-(\d{1,2})-(\d{4})(?:\s+\d{1,2}:\d{2}(?::\d{2})?)?$/);
  if (dmyTime) {
    const dd = String(dmyTime[1]).padStart(2, '0');
    const mm = String(dmyTime[2]).padStart(2, '0');
    const yyyy = dmyTime[3];
    return `${dd}-${mm}-${yyyy}`;
  }
  const dateOnly = str.split(' ')[0];
  return dateOnly.replace(/\//g, '-').replace(/\s+/g, ' ');
}

function formatJamNowJakarta() {
  const parts = new Intl.DateTimeFormat('en-GB', {
    timeZone: 'Asia/Jakarta',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false,
  }).formatToParts(new Date());
  const hh = parts.find(p => p.type === 'hour')?.value || '00';
  const mm = parts.find(p => p.type === 'minute')?.value || '00';
  const ss = parts.find(p => p.type === 'second')?.value || '00';
  return `${hh}.${mm}.${ss}`;
}

const lokasi = getField('Site') || getField('Lokasi Site');
const kegiatan = getField('Kegiatan');
const tanggalRaw =
  getField('Tanggal Kunjungan Cleaning') ||
  getField('Tanggal Kunjungan') ||
  getField('Tanggal Kunjungan ');
const tanggalKunjunganCleaning = formatTanggal(tanggalRaw);
const teknisi = getField('Nama Teknisi');
const keterangan = getField('Keterangan Kunjungan') || getField('Keterangan');
const deskripsi = getField('Deskripsi Pekerjaan');

let matchTimestamp =
  getField('Timestamp') ||
  getField('timestamp') ||
  getField('Waktu') ||
  getField('Created At') ||
  getField('Tanggal Submit') ||
  '';

if (!matchTimestamp) {
  matchTimestamp = new Date().toISOString();
}

const textPlaceholders = {
  '<<Lokasi>>': String(lokasi || ''),
  '<<Tanggal Kunjungan Cleaning>>': String(tanggalKunjunganCleaning || ''),
  '<<Teknisi>>': String(teknisi || ''),
  '<<Kegiatan>>': String(kegiatan || ''),
  '<<Keterangan>>': String(keterangan || ''),
  '<<Deskripsi>>': String(deskripsi || ''),
};

// PRINSIP PENGISIAN MENGALIR: Semua foto mengisi slot berurutan dari <<B1>> s/d <<A5>>
const before = [
  getFileId(getField('BFlink1')),
  getFileId(getField('BFlink2')),
  getFileId(getField('BFlink3')),
  getFileId(getField('BFlink4')),
  getFileId(getField('BFlink5')),
].filter(Boolean);

const saat = [
  getFileId(getField('Slink1')),
  getFileId(getField('Slink2')),
  getFileId(getField('Slink3')),
  getFileId(getField('Slink4')),
  getFileId(getField('Slink5')),
].filter(Boolean);

const after = [
  getFileId(getField('Alink1')),
  getFileId(getField('Alink2')),
  getFileId(getField('Alink3')),
  getFileId(getField('Alink4')),
  getFileId(getField('Alink5')),
].filter(Boolean);

const mergedImages = [...before, ...saat, ...after];

const orderedPlaceholders = [
  '<<B1>>', '<<B2>>', '<<B3>>',
  '<<B4>>', '<<B5>>', '<<S1>>',
  '<<S2>>', '<<S3>>', '<<S4>>',
  '<<S5>>', '<<A1>>', '<<A2>>',
  '<<A3>>', '<<A4>>', '<<A5>>'
];

const imagePlaceholders = orderedPlaceholders.map((placeholder, index) => {
  const fileId = mergedImages[index] || '';
  return {
    placeholder,
    fileId,
    publicImageUrl: fileId
      ? `https://lh3.googleusercontent.com/d/${fileId}`
      : '',
  };
});

const reportName = safeText(
  `Laporan Cleaning ${lokasi} ${tanggalKunjunganCleaning} ${formatJamNowJakarta()}`
);

return [{
  json: {
    config: {
      templateDocId: 'YOUR_TEMPLATE_DOC_ID',
      outputDocFolderId: 'YOUR_OUTPUT_DOC_FOLDER_ID'
    },
    reportName,
    textPlaceholders,
    imagePlaceholders,
    matchTimestamp,
    lokasi,
    kegiatan,
    tanggalKunjunganCleaning,
    teknisi,
    keterangan,
    deskripsi,
    rowNumber: payload.rowNumber || '',
    executionLockId: payload.executionLockId || '',
    originalRow: row
  }
}];

const base = $items('Prepare Incoming Data', 0, 0)[0].json;
const textPlaceholders = base.textPlaceholders || {};
const imagePlaceholders = base.imagePlaceholders || [];
const requests = [];

for (const [placeholder, value] of Object.entries(textPlaceholders)) {
  requests.push({
    replaceAllText: {
      containsText: { text: placeholder, matchCase: true },
      replaceText: value == null ? '' : String(value),
    },
  });
}

if (requests.length === 0) {
  requests.push({
    replaceAllText: {
      containsText: { text: '[[NOOP_EMPTY]]', matchCase: true },
      replaceText: '',
    },
  });
}

return [{
  json: {
    documentId: $json.id,
    docUrl: `https://docs.google.com/document/d/${$json.id}/edit`,
    reportName: base.reportName,
    imagePlaceholders,
    matchTimestamp: base.matchTimestamp,
    requests,
  }
}];

const document = $json;
const base = $items('Build Text Requests', 0, 0)[0].json;
const imagePlaceholders = Array.isArray(base.imagePlaceholders) ? base.imagePlaceholders : [];
const textElements = [];

function scan(elements = []) {
  for (const el of elements) {
    if (el.paragraph?.elements) {
      for (const pe of el.paragraph.elements) {
        const content = pe.textRun?.content || '';
        if (content) {
          textElements.push({
            startIndex: pe.startIndex,
            endIndex: pe.endIndex,
            content,
          });
        }
      }
    }
    if (el.table?.tableRows) {
      for (const row of el.table.tableRows || []) {
        for (const cell of row.tableCells || []) {
          scan(cell.content || []);
        }
      }
    }
    if (el.tableOfContents?.content) {
      scan(el.tableOfContents.content || []);
    }
  }
}

scan(document.body?.content || []);

const allTokens = [];
for (const t of textElements) {
  const regex = /<<[^>]+>>/g;
  let m;
  while ((m = regex.exec(t.content)) !== null) {
    allTokens.push({
      text: m[0],
      startIndex: t.startIndex + m.index,
      endIndex: t.startIndex + m.index + m[0].length,
    });
  }
}

const imageMap = {};
for (const item of imagePlaceholders) {
  if (item?.placeholder) {
    imageMap[item.placeholder] = item.publicImageUrl || '';
  }
}

const requests = [];
allTokens.sort((a, b) => b.startIndex - a.startIndex);

for (const token of allTokens) {
  const imageUrl = imageMap[token.text] || '';

  requests.push({
    deleteContentRange: {
      range: {
        startIndex: token.startIndex,
        endIndex: token.endIndex,
      },
    },
  });

  if (imageUrl) {
    requests.push({
      insertInlineImage: {
        location: { index: token.startIndex },
        uri: imageUrl,
        objectSize: {
          width: { magnitude: 150, unit: 'PT' },
          height: { magnitude: 150, unit: 'PT' },
        },
      },
    });
  }
}

if (requests.length === 0) {
  requests.push({
    replaceAllText: {
      containsText: { text: '[[NOOP_EMPTY_IMG]]', matchCase: true },
      replaceText: '',
    },
  });
}

return [{
  json: {
    documentId: base.documentId,
    docUrl: base.docUrl,
    reportName: base.reportName,
    matchTimestamp: base.matchTimestamp,
    requests,
  }
}];

const reportName = $node["Build Image Requests"].json.reportName;
const matchTimestamp = $node["Build Image Requests"].json.matchTimestamp;
const now = new Date().toISOString();
const executionLockId = $node["Prepare Incoming Data"].json.executionLockId || '';

// Ambil file PDF yang valid dari node Upload PDF to Drive
const uploadPdfNode = $node["Upload PDF to Drive"].json;

let pdfUrl = '';
if (uploadPdfNode.webViewLink) {
  pdfUrl = uploadPdfNode.webViewLink;
} else if (uploadPdfNode.id) {
  pdfUrl = `https://drive.google.com/file/d/${uploadPdfNode.id}/view`;
}

return [{
  json: {
    Timestamp: matchTimestamp,
    'Status Laporan': 'DONE',
    'Nama File Laporan': reportName + '.pdf',
    'Link Doc': '',
    'Link PDF': pdfUrl,
    'Execution Lock ID': executionLockId,
    'Waktu Proses': now
  }
}];
